import test from 'node:test';
import assert from 'node:assert/strict';
import { processLanded, actorLanded, decorationLanded } from '../src/runtime/landing.mjs';

const f = Math.fround;
// Expectations below were captured from the original DLL in the optional
// 294-case native comparison, not generated by this module.
function pawn() {
  const events = [];
  const state = { position: [-1149.24, 825.84, -80.2].map(f), velocity: [100, 20, -300],
    acceleration: [20, -50, 0], physics: 2, radius: 20, height: 43,
    lineCheck(start, end, extent, flags, extra) { events.push({ line: { start, end, extent, flags, extra } }); return { time: .5 }; },
    findSpot() { assert.fail('Unexpected fit attempt'); },
    farMove() { assert.fail('Unexpected relocation'); },
    random() { assert.fail('Unexpected random call'); },
    landedEvent(normal) { events.push({ landed: normal, velocity: [...state.velocity] }); },
    setPhysics(physics, actor) { events.push({ setPhysics: physics, actor }); state.physics = physics; },
    walking(remaining, iterations) { events.push({ walking: remaining, iterations, acceleration: [...state.acceleration], velocity: [...state.velocity] }); },
  };
  return { state, events };
}
const hit = { normal: [0, 0, 1], actor: 'floor' };

test('landing uses the original support query and retains vertical velocity before walking physics', () => {
  const { state, events } = pawn();
  processLanded(state, hit, f(.01), 1);
  assert.deepEqual(events, [
    { line: { start: [-1149.239990234375, 825.8400268554688, -80.19999694824219],
      end: [-1149.239990234375, 825.8400268554688, -92.19999694824219],
      extent: [18, 18, 38.70000076293945], flags: 55, extra: 0 } },
    { landed: [0, 0, 1], velocity: [100, 20, -300] }, { setPhysics: 1, actor: 'floor' },
  ]);
  assert.deepEqual(state.acceleration, [0.3713906705379486, -0.9284766912460327, 0]);
  assert.deepEqual(state.velocity, [100, 20, -300]);
});

test('landing dispatches unused time above double 0.01 with normalized acceleration', () => {
  const { state, events } = pawn();
  processLanded(state, hit, f(.0100000008), 1);
  assert.deepEqual(events.at(-1), { walking: 0.010000000707805157, iterations: 1,
    acceleration: [0.3713906705379486, -0.9284766912460327, 0], velocity: [100, 20, -300] });
});

test('an event changing physics prevents default walking and acceleration normalization', () => {
  const { state, events } = pawn();
  state.landedEvent = () => { state.physics = 0; };
  processLanded(state, hit, .2, 7);
  assert.equal(events.length, 1);
  assert.deepEqual(state.acceleration, [20, -50, 0]);
  assert.equal(state.physics, 0);
});

test('a changed fitted position keeps falling and perturbs velocity even when relocation fails', () => {
  const { state, events } = pawn(), start = [...state.position];
  state.lineCheck = () => ({ time: 1 });
  state.findSpot = (position, extent, ...options) => {
    assert.deepEqual(position, start); assert.deepEqual(extent, [22, 22, 47.29999923706055]);
    assert.deepEqual(options, [0, 0]); return [1, 2, 3];
  };
  state.farMove = (position, ...options) => {
    events.push('farMove'); assert.deepEqual(position, [1, 2, 3]); assert.deepEqual(options, [0, 0]); return false;
  };
  const integers = [30001, 12345];
  state.random = () => { events.push('rand'); return integers.shift() * f(1 / 32767); };
  processLanded(state, hit, f(1 / 120), 1);
  assert.deepEqual(events, ['farMove', 'rand', 'rand']);
  assert.deepEqual(state.position, start);
  assert.deepEqual(state.velocity, [124.93515014648438, 12.605059623718262, -300]);
  assert.deepEqual(state.acceleration, [20, -50, 0]);
  assert.equal(state.physics, 2);
});

// Non-Decoration non-Pawn (inventory/projectile ancestry) and bBounceVelocity
// landings, captured from the original by scripts/validate-native-landing.mjs.
function actor(changes = {}) {
  const events = [];
  const state = { velocity: [80, -20, -120], acceleration: [0, 0, 0], physics: 2, landingCounter: 0x5a5a5a5a,
    landedEvent(normal) { events.push({ landed: normal }); },
    setPhysics(physics, floor) { events.push({ setPhysics: physics, floor }); state.physics = physics; state.velocity = [0, 0, 0]; },
    ...changes,
  };
  return { state, events };
}

test('an inventory or projectile landing is Landed then PHYS_None, leaving subclass fields alone', () => {
  const { state, events } = actor();
  actorLanded(state, hit);
  assert.deepEqual(events, [{ landed: [0, 0, 1] }, { setPhysics: 0, floor: 'floor' }]);
  assert.equal(state.landingCounter, 0x5a5a5a5a);
  const walking = actor({ landedEvent() { walking.state.physics = 1; } });
  actorLanded(walking.state, hit);
  assert.equal(walking.state.physics, 1); // no setPhysics and no walking continuation for a non-Pawn
});

test('a bBounceVelocity zone bounces a non-Pawn instead of landing it', () => {
  const zone = { bBounceVelocity: true, ZoneVelocity: [-0, 0, 5] };
  for (const land of [actorLanded, decorationLanded]) {
    const { state, events } = actor({ landingCounter: 5 });
    land(state, hit, { zone });
    assert.deepEqual(events, []);
    assert.ok(Object.is(state.velocity[0], 0) && state.velocity[2] === 85);
    assert.equal(state.landingCounter, 5);
  }
  const still = actor();
  actorLanded(still.state, hit, { zone: { bBounceVelocity: true, ZoneVelocity: [-0, 0, -0] } });
  assert.equal(still.events.length, 2); // -0 components compare equal to zero
});

// processLanded (Engine.dll 0x103cf52d) takes appFrand's x87 result unrounded: Stage 5 led1's original Velocity.X -15.166173 is f32(8101 * f32(1/32767) * 60 - 30);
// the pawn physics service had rounded the product to float32 first (-15.1661739).
import {ScriptRuntime} from '../src/runtime/script-runtime.mjs';
import {createNativeRng} from '../src/runtime/rng.mjs';
test('the pawn physics random service does not round appFrand to float32', () => {
  const runtime = new ScriptRuntime({});
  runtime.levelFor = () => ({hash: {}});
  runtime.rng = createNativeRng(0x33d53323 - 1 >>> 0);
  const seed = runtime.rng.state;
  const probe = createNativeRng(seed), expected = probe.frand();
  const value = runtime.pawnPhysicsServices({}).random();
  assert.equal(value, expected);
  assert.notEqual(value, Math.fround(value));
});
